styles.tutorial:
section[data-skill-hub] .-w {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  grid-template-rows: auto calc(var(--vh,1vh) * 25) auto auto calc(var(--h1) * 2);
  column-gap: var(--g-gap);
}

section[data-skill-hub] svg {
  width: 100%;
  aspect-ratio: 568 / 334;
  fill: var(--c-white);
}
section[data-skill-hub] .vilnius {
  grid-column-start: 1;
  grid-column-end: 7;
  grid-row-start: 3;
  grid-row-end: 4;
  position: relative;
  z-index: 1;
}
section[data-skill-hub] .festival {
  grid-column-start: 1;
  grid-column-end: 7;
  grid-row-start: 4;
  grid-row-end: 5;
  position: relative;
  z-index: 3;
}

section[data-skill-hub] .sequence {
  grid-column-start: 2;
  grid-column-end: 6;
  grid-row-start: 3;
  grid-row-end: 5;
  justify-self: center;
  align-self: center;
  position: relative;
  z-index: 2;
  display: grid;
  place-items: center;
  background-color: var(--c-black);
}
section[data-skill-hub] .sequence figure {
  grid-area: 1/1;
  aspect-ratio: 408/280;
  position: relative;
  z-index: 1;
  transform: translateZ(0);
  opacity: 0;
  transition: opacity 0.9s var(--easing-function-2), clip-path 0.9s var(--easing-function-2);
}
section[data-skill-hub] .sequence figure img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
section[data-skill-hub] .sequence figure.-leaving {
  z-index: 2;
  opacity: 0;
}
section[data-skill-hub] .sequence figure.-entering {
  opacity: 1;
  clip-path: polygon(40% 40%, 60% 40%, 60% 60%, 40% 60%);
  transition: opacity 0s linear, clip-path 0s linear;
}
section[data-skill-hub] .sequence figure.-active {
  z-index: 3;
  opacity: 1;
  clip-path: polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%);
}

section[data-skill-hub] nav.pages {
  grid-column-start: 2;
  grid-column-end: 6;
  grid-row-start: 3;
  grid-row-end: 5;
  align-self: center;
  justify-self: center;
  position: relative;
  z-index: 4;
  display: flex;
  gap: var(--g-gap);
  margin-top: calc( var(--h2) * 2 );
}
section[data-skill-hub] nav.pages span {
  background-color: var(--c-black);
  color: var(--c-white);
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: var(--h5);
  width: var(--h4);
  height: var(--h4);
  cursor: pointer;
}
section[data-skill-hub] nav.pages span.-entering,
section[data-skill-hub] nav.pages span.-active {
  background-color: var(--c-red);
  color: var(--c-white);
}
section[data-skill-hub] nav.arrows {
  grid-column-start: 2;
  grid-column-end: 4;
  grid-row-start: 1;
  grid-row-end: 2;
  justify-self: start;
  position: sticky;
  top: calc( var(--h6) * 6 );
  z-index: 4;
  display: flex;
  align-items: center;
  gap: var(--g-gap);
}
section[data-skill-hub] nav.arrows span {
  border: 2px solid var(--c-white);
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: var(--h5);
  width: var(--h4);
  height: var(--h4);
  cursor: pointer;
}
section[data-skill-hub] .mini-sequence {
  grid-column-start: 4;
  grid-column-end: 6;
  grid-row-start: 1;
  grid-row-end: 2;
  align-self: center;
  position: sticky;
  top: calc( var(--h6) * 6 );
  z-index: 4;
  display: grid;
  place-items: center;
  contain: paint;
}
section[data-skill-hub] .mini-sequence figure {
  grid-area: 1/1;
  aspect-ratio: 408/280;
  position: relative;
  z-index: 1;
  transform: translateZ(0);
  opacity: 0;
  translate: 0 0%;
  transition: opacity 0s linear, translate 0s linear;
}
section[data-skill-hub] .mini-sequence figure img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

section[data-skill-hub] .mini-sequence figure.-leaving {
  z-index: 2;
  opacity: 0;
  translate: 0 -50%;
  transition: opacity 0.6s var(--easing-function-2), translate 0.6s var(--easing-function-2);
}
section[data-skill-hub] .mini-sequence figure.-active {
  z-index: 3;
  opacity: 1;
  translate: 0 0%;
  transition: translate 0.6s var(--easing-function-2);
}
section[data-skill-hub] .mini-sequence figure.-entering {
  opacity: 1;
  translate: 0 100%;
  transition: opacity 0s linear, translate 0s linear;
}





@media (min-width: 1024px) {
  section[data-skill-hub] .-w {
    grid-template-columns: repeat(14, 1fr);
  }
  section[data-skill-hub] .vilnius {
    grid-column-start: 5;
    grid-column-end: 11;
  }
  section[data-skill-hub] .festival {
    grid-column-start: 5;
    grid-column-end: 11;
  }
  section[data-skill-hub] .sequence {
    grid-column-start: 6;
    grid-column-end: 10;
  }
  section[data-skill-hub] nav.arrows {
    grid-column-start: 3;
    grid-column-end: 5;
  }
  section[data-skill-hub] nav.pages {
    grid-column-start: 3;
    grid-column-end: 13;
  }
  section[data-skill-hub] nav.pages span {
    font-size: var(--p);
    width: var(--h5);
    height: var(--h5);
  }
  section[data-skill-hub] nav span:hover {
    background-color: var(--c-white);
    color: var(--c-black);
  }
  section[data-skill-hub] .mini-sequence {
    grid-column-start: 12;
    grid-column-end: 13;
  }
}




